import 'package:flutter/material.dart';

/// Languages the whole app can be switched to from the Me tab.
enum AppLang {
  en('English', 'English'),
  hi('हिन्दी', 'Hindi'),
  mr('मराठी', 'Marathi'),
  kn('ಕನ್ನಡ', 'Kannada'),
  ml('മലയാളം', 'Malayalam'),
  te('తెలుగు', 'Telugu');

  const AppLang(this.native, this.english);

  final String native;
  final String english;
}

class LocaleController extends ValueNotifier<AppLang> {
  LocaleController([super.value = AppLang.en]);

  AppLang get lang => value;
}

/// Widgets that call [tr] rebuild automatically when the language changes.
class AppLocale extends InheritedNotifier<LocaleController> {
  const AppLocale({
    super.key,
    required LocaleController controller,
    required super.child,
  }) : super(notifier: controller);

  static LocaleController of(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<AppLocale>()!.notifier!;
}

/// Looks up [key] in the current language. Falls back to English, then the key.
/// `{name}` placeholders are filled from [args].
String tr(BuildContext context, String key, {Map<String, String>? args}) {
  final lang = AppLocale.of(context).lang;
  final row = _strings[key];
  var text = row == null ? key : (row[lang.index].isEmpty ? row[0] : row[lang.index]);
  args?.forEach((k, v) => text = text.replaceAll('{$k}', v));
  return text;
}

/// Positive/negative letter spacing breaks conjuncts in Indic scripts,
/// so decorative spacing is only applied for English.
double spacing(BuildContext context, double value) =>
    AppLocale.of(context).lang == AppLang.en ? value : 0;

